#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

long long fastPower(long long base, long long exp) {
    long long result = 1LL;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

long long modularInverse(long long x) {
    return fastPower(x, mod - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, l, r;
    cin >> n >> m >> l >> r;

    if (l == r) {
        cout << 1 << "\n";
        return 0;
    }

    long long odds = ((r + 1) / 2) - (l / 2);
    long long evens = (r / 2) - ((l - 1) / 2);
    long long total = n * m;

    long long ans;
    if (total % 2 == 1) {
        ans = fastPower(odds + evens, total);
    } else {
        long long sum = (fastPower(odds + evens, total) + fastPower(odds - evens, total)) % mod;
        ans = (sum * modularInverse(2)) % mod;
    }
    cout << ans << "\n";

    return 0;
}
